  request_reservation_deletion: {"name":"deskilo_request_reservation_deletion","title":"Ask to delete a started booking","description":"Ask to delete one of the person's own bookings that has ALREADY started. Depending on the workspace's validation rules it is deleted at once (status completed) or a validator must approve it first (status pending_validation: tell the person it is not deleted yet). A booking that has not started is cancelled directly with deskilo_cancel_reservation instead.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"reservation_id":{"type":"string","format":"uuid","description":"A reservation_id from deskilo_list_my_reservations."},"reason":{"type":"string","maxLength":500,"description":"Optional: why the booking is cancelled, shown to whoever validates it."},"expected_state":{"type":"string","maxLength":64,"description":"Optional: the state_digest you last read for this reservation. If it changed since, nothing happens and the answer is a conflict carrying the current state."}},"required":["request_id","workspace_id","reservation_id"]},"outputSchema":{"type":"object","required":["status"],"properties":{"schema_version":{"const":1},"request_id":{"type":"string","format":"uuid"},"operation":{"const":"request_reservation_deletion"},"workspace_id":{"type":"string","format":"uuid"},"status":{"enum":["completed","pending_validation","requires_confirmation","denied","conflict","validation_error","not_found","rate_limited"]},"data":{"type":"object"},"event_id":{"type":"string","format":"uuid"},"error":{"type":"object","properties":{"code":{"type":"string"},"fields":{"type":"object","additionalProperties":{"type":"string"}}}}}},"annotations":{"title":"Ask to delete a started booking","readOnlyHint":false,"destructiveHint":true,"idempotentHint":true,"openWorldHint":false}},
  request_invoice_issue: {"name":"deskilo_request_invoice_issue","title":"Request an invoice","description":"Staff only: ask for a member's invoice for one month to be issued. Needs the person's confirmation in the DesKilo app first (status requires_confirmation), then the workspace's validation rules.","inputSchema":{"type":"object","additionalProperties":false,"properties":{"request_id":{"type":"string","format":"uuid","description":"A new random UUID for each distinct intent. Reuse the SAME request_id, with the same arguments, only to retry that intent (after a timeout, or after the person confirmed it in the DesKilo app): it never acts twice.","examples":["6b1d3f0e-0000-4000-8000-000000000001"]},"workspace_id":{"type":"string","format":"uuid","description":"The workspace to act in: a workspace_id from deskilo_list_workspaces. Never guess it.","examples":["00000000-0000-4000-8000-0000000000a1"]},"member_id":{"type":"string","format":"uuid","description":"The member this request is about."},"period":{"type":"string","pattern":"^\\d{4}-(0[1-9]|1[0-2])$","description":"The month, as YYYY-MM.","examples":["2026-09"]},"kind":{"type":"string","enum":["full","subscription","usage"],"description":"Which invoice: full (subscription and usage), subscription only, or usage only.","examples":["full"]}},"required":["request_id","workspace_id","member_id","period"]},"outputSchema":{"type":"object","required":["status"],"properties":{"schema_version":{"const":1},"request_id":{"type":"string","format":"uuid"},"operation":{"const":"request_invoice_issue"},"workspace_id":{"type":"string","format":"uuid"},"status":{"enum":["completed","pending_validation","requires_confirmation","denied","conflict","validation_error","not_found","rate_limited"]},"data":{"type":"object"},"event_id":{"type":"string","format":"uuid"},"error":{"type":"object","properties":{"code":{"type":"string"},"fields":{"type":"object","additionalProperties":{"type":"string"}}}}}},"annotations":{"title":"Request an invoice","readOnlyHint":false,"destructiveHint":false,"idempotentHint":true,"openWorldHint":false}},
